//! A minimal URL parser re-implementing the behavior of the C++
//! `url_parser::URL` class (black-box compatible).

mod port;

/// A parsed URL, exposing the same accessors as the C++ `url_parser::URL`.
pub struct URL {
    scheme: String,
    authority: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    valid: bool,
}

impl URL {
    /// Parse `url` into its components.
    pub fn new(url: &str) -> URL {
        let mut scheme = String::new();
        let mut authority = String::new();
        let mut path = String::new();
        let mut query = String::new();
        let mut fragment = String::new();
        let mut port_num: i32 = -1;

        // Scheme: everything before "://", lower-cased, if present.
        let mut rest = url;
        let has_authority = match url.find("://") {
            Some(pos) => {
                scheme = url[..pos].to_ascii_lowercase();
                rest = &url[pos + 3..];
                true
            }
            None => false,
        };

        // Fragment: everything after the first '#'.
        if let Some(pos) = rest.find('#') {
            fragment = rest[pos + 1..].to_string();
            rest = &rest[..pos];
        }

        // Query: everything after the first '?'.
        if let Some(pos) = rest.find('?') {
            query = rest[pos + 1..].to_string();
            rest = &rest[..pos];
        }

        // The authority/path split only happens when "://" was present.
        if has_authority {
            match rest.find('/') {
                Some(pos) => {
                    authority = rest[..pos].to_string();
                    path = rest[pos..].to_string();
                }
                None => {
                    authority = rest.to_string();
                }
            }

            // Port: first ':' after the last '@' in the authority. The
            // authority is rebuilt from the host part plus the normalized
            // port; an invalid port is dropped entirely.
            let start = authority.rfind('@').map(|i| i + 1).unwrap_or(0);
            if let Some(rel) = authority[start..].find(':') {
                let colon = start + rel;
                let candidate = &authority[colon + 1..];
                let host = authority[..colon].to_string();
                authority = match port::parse_stoi(candidate) {
                    Some(p) if (0..=65535).contains(&p) => {
                        port_num = p as i32;
                        format!("{}:{}", host, p)
                    }
                    _ => host,
                };
            }
        } else {
            path = rest.to_string();
        }

        let valid = !authority.is_empty() || !path.is_empty();

        URL {
            scheme,
            authority,
            port: port_num,
            path,
            query,
            fragment,
            valid,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}

